"use strict";

const IS_JA=document.documentElement.lang==='ja';
const SKY_TEMPLE_DATA=window.AimDojoSkyTemple||null;
const SKY_MAPS=window.AimDojoSkyMaps||null;   // Temple Orbs: equirectangular sky/planet map table (pure, THREE-free); null degrades to glyph-only
const T=(key,en)=>(IS_JA&&window.JA&&window.JA[key]!=null)?window.JA[key]:en;
function TF(key,en,values){
  let out=T(key,en);
  for(const name of Object.keys(values||{})) out=out.split('{'+name+'}').join(String(values[name]));
  return out;
}
function songDisplay(name){ return name==='MOONLIGHT'?T('songMoonlight',name):name; }

const TONE_JS='https://cdnjs.cloudflare.com/ajax/libs/tone/14.8.49/Tone.js';
const lazyScripts={};
function loadScriptOnce(src){
  return lazyScripts[src] || (lazyScripts[src]=new Promise((resolve,reject)=>{
    const s=document.createElement('script'); s.src=src; s.async=true;
    s.onload=()=>resolve(s);
    s.onerror=()=>{ delete lazyScripts[src]; reject(new Error('script load failed: '+src)); };
    document.head.appendChild(s);
  }));
}
let toneLoadFailed=false;
function loadToneOnce(){
  if(window.Tone){ toneLoadFailed=false; return Promise.resolve(window.Tone); }
  toneLoadFailed=false;
  return loadScriptOnce(TONE_JS).then(()=>{ if(!window.Tone) throw new Error('Tone missing after load'); toneLoadFailed=false; return window.Tone; }).catch(e=>{ toneLoadFailed=true; throw e; });
}

